def extra_chapters():
    result = {}
    for species, (names, content) in DATA.items():
        rows = content.strip().splitlines()
        names = names.split(";")
        if len(names) != 10 or len(rows) != 10:
            raise ValueError(f"Expected ten chapters for {species}")
        result[species] = [(name, "\n".join(part.strip() for part in row.split("/")))
                           for name, row in zip(names, rows)]
    return result
